python3 -c "
import sys, json, re
try:
    d = json.load(sys.stdin)
except Exception:
    sys.exit(0)
path = d.get('file_path', d.get('path', ''))
content = d.get('new_string', d.get('content', ''))
if re.search(r'(billing|credits|webhook)', path) and re.search(r'delta', content):
    deltas = re.findall(r'delta[^,\n}]+', content)
    for delta in deltas:
        nums = re.findall(r'[-+]?\d+', delta)
        for n in nums:
            if int(n) > 0 and 'purchase' not in content.lower() and 'signup' not in content.lower() and 'bonus' not in content.lower():
                print(f'AVISO BILLING: delta positivo ({n}) detectado em arquivo de billing. Debitos devem ser negativos. Verifique se isso esta correto antes de continuar.', file=sys.stderr)
                break
"
